using namespace std;

class Solution {
public:
    string reverseLettersAndSpecial(string s) {
        string res = s;
        vector<int> letters, specials;
        for (int i = 0; i < (int)s.size(); i++) {
            if (isalpha(s[i])) letters.push_back(i);
            else specials.push_back(i);
        }
        int l = 0, r = (int)letters.size() - 1;
        while (l < r) {
            swap(res[letters[l]], res[letters[r]]);
            l++; r--;
        }
        l = 0; r = (int)specials.size() - 1;
        while (l < r) {
            swap(res[specials[l]], res[specials[r]]);
            l++; r--;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String reverseLettersAndSpecial(String s) {
        char[] res = s.toCharArray();
        List<Integer> letters = new ArrayList<>();
        List<Integer> specials = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            if (Character.isLetter(s.charAt(i))) letters.add(i);
            else specials.add(i);
        }
        int l = 0, r = letters.size() - 1;
        while (l < r) {
            char tmp = res[letters.get(l)];
            res[letters.get(l)] = res[letters.get(r)];
            res[letters.get(r)] = tmp;
            l++; r--;
        }
        l = 0; r = specials.size() - 1;
        while (l < r) {
            char tmp = res[specials.get(l)];
            res[specials.get(l)] = res[specials.get(r)];
            res[specials.get(r)] = tmp;
            l++; r--;
        }
        return new String(res);
    }
}

var reverseLettersAndSpecial = function(s) {
    const res = s.split('');
    const letters = [];
    const specials = [];
    for (let i = 0; i < s.length; i++) {
        if (/[a-zA-Z]/.test(s[i])) letters.push(i);
        else specials.push(i);
    }
    let l = 0, r = letters.length - 1;
    while (l < r) {
        const tmp = res[letters[l]];
        res[letters[l]] = res[letters[r]];
        res[letters[r]] = tmp;
        l++; r--;
    }
    l = 0; r = specials.length - 1;
    while (l < r) {
        const tmp = res[specials[l]];
        res[specials[l]] = res[specials[r]];
        res[specials[r]] = tmp;
        l++; r--;
    }
    return res.join('');
};
